GRANT SELECT ON public.daily_spins TO authenticated;
CREATE POLICY daily_spins_admin_read ON public.daily_spins FOR SELECT TO authenticated USING (public.daily_is_admin());
CREATE POLICY daily_players_admin_read ON public.daily_players FOR SELECT TO authenticated USING (public.daily_is_admin());
CREATE OR REPLACE FUNCTION public.daily_admin_report() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.daily_is_admin() THEN RAISE EXCEPTION 'not_authorized'; END IF; RETURN jsonb_build_object('players',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'coins',coins,'blocked',blocked) ORDER BY coins DESC),'[]'::jsonb) FROM public.daily_players),'checkins',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY day DESC),'[]'::jsonb) FROM (SELECT player_id,day,coins FROM public.daily_checkins ORDER BY day DESC LIMIT 200) c),'spins',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY created_at DESC),'[]'::jsonb) FROM (SELECT player_id,value,created_at FROM public.daily_spins ORDER BY created_at DESC LIMIT 100) x)); END $$;
REVOKE ALL ON FUNCTION public.daily_admin_report() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_admin_report() TO authenticated;